<?php

namespace App\Services\Sms;

use App\Enums\SmsEncoding;

/**
 * One outbound message the dispatcher asks the provider to deliver.
 *
 * The reference is generated by OmniCast before the message is submitted, so a
 * delivery receipt can always be matched to the message even when the provider
 * has not assigned a message id yet.
 */
final class OutboundSms
{
    public function __construct(
        public readonly string $reference,
        public readonly string $to,
        public readonly string $from,
        public readonly string $body,
        public readonly SmsEncoding $encoding = SmsEncoding::Gsm7,
        public readonly int $segments = 1,
    ) {}

    /**
     * Whether the body carries characters outside the GSM 03.38 alphabet.
     */
    public function isUnicode(): bool
    {
        return $this->encoding === SmsEncoding::Unicode;
    }

    public function isMultipart(): bool
    {
        return $this->segments > 1;
    }

    /**
     * The signed URL a provider posts the delivery receipt to.
     *
     * Providers that need a per-message `dlr-url` (Kannel, generic gateways) get
     * the reference and its signature in the query string, so a receipt can be
     * verified without a request body.
     */
    public function deliveryUrl(): ?string
    {
        $secret = (string) config('sms.webhook.secret');

        if ($secret === '') {
            return null;
        }

        return route('webhooks.sms', [
            'reference' => $this->reference,
            'sig' => hash_hmac('sha256', $this->reference, $secret),
        ]);
    }

    /**
     * The recipient in the form a log line may show it.
     */
    public function maskedTo(): string
    {
        $digits = preg_replace('/\D+/', '', $this->to) ?? '';

        return strlen($digits) > 4 ? '***'.substr($digits, -4) : '***';
    }
}
